(()=>{'use strict';const {Designer,controls}=OIBPrototype,d=new Designer(),$=id=>document.getElementById(id),root=$('designer');
const el=(tag,text)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;return x};
function message(s,error=false){$('message').textContent=s;$('message').setAttribute('role',error?'alert':'status');}
function act(fn,success){try{fn();render();if(success)message(success);}catch(e){message(e.message,true);}}
function button(text,fn){const b=el('button',text);b.type='button';b.onclick=fn;return b;}
function modal(title,body,actions){$('modal-title').textContent=title;$('modal-body').replaceChildren(body);$('modal-actions').replaceChildren(...actions,button('Cancel',()=>$('modal').close()));$('modal').showModal();}
function closeAct(fn,text){act(()=>{fn();$('modal').close();},text);}
function selected(){return d.draft.nodes.find(n=>n.id===d.selection);}
function widget(kind,node,key){const box=el('div');box.className='widget';box.dataset.kind=kind;const val=d.values[key];const save=v=>{d.setValue(key,v);message('Sample '+kind+' = '+v+' · local Test state');};
const input=(type,value,label=node.label)=>{const x=el('input');x.type=type;x.value=val??value;x.setAttribute('aria-label',label);x.oninput=()=>{save(type==='checkbox'?x.checked:x.value);if(x.nextSibling?.tagName==='OUTPUT')x.nextSibling.textContent=x.value};return x;};
const action=(text,fn)=>box.append(button(text,fn));
if(kind==='Text')box.append(el('span',node.label));
else if(kind==='Button'){action(node.label,()=>save((Number(d.values[key])||0)+1));}
else if(kind==='Toggle'){const label=el('label'),x=input('checkbox','',node.label);x.checked=!!val;label.append(x,el('span',node.label));box.append(label);}
else if(kind==='Slider'){const x=input('range',40);x.min=0;x.max=100;box.append(x,el('output',x.value));}
else if(kind==='TextField'||kind==='NumberField'){box.append(input(kind==='TextField'?'text':'number',kind==='TextField'?'Sample text':12));}
else if(kind==='Select'||kind==='Menu'){const s=el('select');s.setAttribute('aria-label',node.label);for(const name of ['Low','Medium','High']){const o=el('option',name);s.append(o)}s.value=val??'Medium';s.onchange=()=>save(s.value);box.append(s);}
else if(kind==='Segments'||kind==='Tabs'){for(const name of ['One','Two','Three']){const b=button(name,()=>{save(name);for(const b of box.querySelectorAll('button'))b.setAttribute('aria-pressed',b.textContent===name);if(kind==='Tabs')box.querySelector('p').textContent='Content: '+name});b.setAttribute('aria-pressed',(val??'One')===name);box.append(b)}if(kind==='Tabs')box.append(el('p','Content: '+(val??'One')));}
else if(kind==='Progress'){const p=el('progress');p.max=100;p.value=Number(val??40);p.setAttribute('aria-label',node.label);box.append(p);action('Advance sample',()=>{save(Math.min(100,Number(d.values[key]??40)+10));p.value=d.values[key]});}
else if(kind==='List'){for(const name of ['Audio','Display','Network'])action(name,()=>save(name));}
else if(kind==='Dialog'){action('Open confirmation',()=>modal('Remove sample item?',el('p','This changes sample state only.'),[button('Remove sample',()=>{save('confirmed');$('modal').close()})]));}
else if(kind==='Stepper'){action('−',()=>{save(Number(d.values[key]??5)-1);box.querySelector('output').textContent=d.values[key]});box.append(el('output',String(val??5)));action('+',()=>{save(Number(d.values[key]??5)+1);box.querySelector('output').textContent=d.values[key]});}
else if(kind==='RangeSlider'){const pair=Array.isArray(val)?val:[20,80];for(let i=0;i<2;i++){const x=el('input');x.type='range';x.min=0;x.max=100;x.value=pair[i];x.setAttribute('aria-label',i?'Upper value':'Lower value');x.oninput=()=>{const next=[...(d.values[key]??pair)];next[i]=Number(x.value);next[i]=i?Math.max(next[0],next[i]):Math.min(next[1],next[i]);save(next);const sliders=box.querySelectorAll('input');sliders[0].value=next[0];sliders[1].value=next[1];box.querySelector('output').textContent=next.join(' – ')};box.append(x)}box.append(el('output',pair.join(' – ')));}
else if(kind==='Status'){box.append(el('span',val??'Ready'));action('Change sample state',()=>{save(d.values[key]==='Complete'?'Ready':'Complete');box.querySelector('span').textContent=d.values[key]});}
else {const definition=d.catalog[kind];box.style.display='grid';for(const child of definition?.nodes??[])box.append(widget(child.ref,child,key+'/'+child.id));}
if(!d.test)for(const x of box.querySelectorAll('input,button,select')){x.disabled=true;}return box;}
function renderPreview(){const f=$('component'),l=d.draft.layout,align=l.alignment??0;f.replaceChildren();const colors=d.draft.colors?.[d.mode]??(d.mode==='Dark'?{background:'#101010',text:'#f5f5f5'}:{background:'#f4f4f4',text:'#151515'});Object.assign(f.style,{flexDirection:l.flow,gap:l.gap+'px',padding:l.padding??16,width:l.width==='Fill'?'100%':l.width==='Hug'?'max-content':(l.fixedW??300)+'px',height:l.height==='Fixed'?'260px':l.height==='Fill'?'320px':'auto',alignItems:['flex-start','center','flex-end'][l.flow==='column'?align%3:Math.floor(align/3)],justifyContent:['flex-start','center','flex-end'][l.flow==='column'?Math.floor(align/3):align%3],background:colors.background,color:colors.text});f.style.padding=(l.padding??16)+'px';if(!d.draft.nodes.length){const blank=el('p',d.draft.empty?'No components yet · choose New component':'Blank component · add a Text or control from Library');blank.className='muted';f.append(blank);}for(const n of d.draft.nodes){const part=el('div');part.className='part'+(d.selection===n.id?' selected':'');part.dataset.node=n.id;const pick=button(n.label+' · '+n.ref,()=>{d.selection=n.id;render()});pick.className='pick';pick.hidden=d.test;part.append(pick,widget(n.ref,n,n.id));f.append(part);} $('background').value=colors.background;$('text-color').value=colors.text;$('instance-sample').style.color=d.resolve('A','text',colors.text);$('instance-sample').textContent=d.draft.name+' · Sample instance A';$('instance-source').textContent=d.overrides.A?.text?'Source: instance override':'Source: style → text_primary / '+d.mode;}
function render(){root.dataset.mode=d.mode;$('component-title').textContent=d.draft.name+(d.draft.retired?' · Retired':'');$('draft-status').textContent=d.dirty?'Local draft · not applied':'Confirmed model';$('revision').textContent='Confirmed g'+d.generation+' / draft base g'+d.base;$('name').value=d.draft.name;$('name').disabled=!!d.draft.empty;for(const id of ['flow','gap','width','height'])$(id).value=d.draft.layout[id];$('fixed-w').value=d.draft.layout.fixedW??300;$('padding').value=d.draft.layout.padding??16;$('apply').disabled=!d.dirty;$('undo').disabled=!d.history.length;$('redo').disabled=!d.future.length;$('discard').disabled=!d.dirty;$('edit-mode').setAttribute('aria-pressed',!d.test);$('test-mode').setAttribute('aria-pressed',d.test);$('definitions').replaceChildren(...Object.values(d.catalog).filter(x=>!x.builtin).map(x=>button(x.name+(x.retired?' · Retired':''),()=>act(()=>d.open(x.id),'Opened definition.'))));$('insert-kind').replaceChildren(...Object.values(d.catalog).filter(x=>!x.retired).map(x=>{const o=el('option',x.name);o.value=x.id;return o}));$('layers').replaceChildren(...d.draft.nodes.map(n=>button(n.label+' / '+n.ref,()=>{d.selection=n.id;render()})));const s=selected();$('node-label').disabled=!s;$('node-label').value=s?.label??'';$('selection-info').textContent=s?'Selected '+s.ref+' · '+s.id:'Select a layer to edit or expose its value';$('api').textContent='Exposed: '+(Object.keys(d.draft.api).join(', ')||'none');$('uses').textContent=d.uses(d.draft.id).length+' confirmed reference(s) in this model. External installed apps are not inventoried.';renderPreview();}
$('new').onclick=()=>{const input=el('input');input.id='new-name';input.value='Untitled component';input.setAttribute('aria-label','New component name');modal('New blank component',input,[button('Create blank',()=>closeAct(()=>d.create(input.value),'Created local blank draft.'))]);};
$('insert').onclick=()=>act(()=>d.insert($('insert-kind').value),'Inserted reference in local draft.');$('apply').onclick=()=>act(()=>d.apply(),'Applied atomically to the in-memory model.');$('discard').onclick=()=>act(()=>d.discard(),'Discarded local changes.');$('undo').onclick=()=>act(()=>d.undo());$('redo').onclick=()=>act(()=>d.redo());
for(const [id,key]of [['name','name'],['node-label','label']])$(id).onchange=e=>act(()=>d.change(x=>{if(key==='name')x.name=e.target.value;else selected().label=e.target.value}));
for(const id of ['flow','width','height','gap','padding','fixed-w'])$(id).onchange=e=>act(()=>d.change(x=>x.layout[id==='fixed-w'?'fixedW':id]=['gap','padding','fixed-w'].includes(id)?Number(e.target.value):e.target.value));
for(let i=0;i<9;i++){$('align').append(button(['↖','↑','↗','←','·','→','↙','↓','↘'][i],()=>act(()=>d.change(x=>x.layout.alignment=i))));$('align').lastChild.setAttribute('aria-label','Alignment '+['top left','top center','top right','center left','center','center right','bottom left','bottom center','bottom right'][i]);}
$('earlier').onclick=()=>act(()=>d.move(d.selection,-1));$('later').onclick=()=>act(()=>d.move(d.selection,1));$('remove-node').onclick=()=>{modal('Remove selected node?',el('p','Its exposed properties are removed in the draft too. The referenced definition remains.'),[button('Remove node',()=>closeAct(()=>d.removeNode(d.selection),'Removed from draft. Apply to confirm.'))]);};
$('appearance').onchange=e=>{d.mode=e.target.value;render()};$('profile').onchange=e=>root.classList.toggle('frame',e.target.value==='Frame');for(const b of root.querySelectorAll('[data-pane]'))if(b.tagName==='BUTTON')b.onclick=()=>{root.dataset.pane=b.dataset.pane};
$('edit-mode').onclick=()=>{d.test=false;render()};$('test-mode').onclick=()=>{d.test=true;render()};
for(const [id,key]of [['background','background'],['text-color','text']])$(id).onchange=e=>act(()=>d.change(x=>{x.colors??={};x.colors[d.mode]??=d.mode==='Dark'?{background:'#101010',text:'#f5f5f5'}:{background:'#f4f4f4',text:'#151515'};x.colors[d.mode][key]=e.target.value}));
$('override').onclick=()=>act(()=>d.setOverride('A','text',$('instance-color').value));$('reset').onclick=()=>act(()=>d.resetOverride('A','text'));$('expose').onclick=()=>act(()=>d.expose(d.selection,$('property-name').value,$('property-type').value),'Exposed typed property in draft.');
$('retire').onclick=()=>modal('Retire '+d.draft.name+'?',el('p','Existing references continue to work. New insertion is blocked in this model.'),[button('Retire definition',()=>closeAct(()=>d.retire(d.draft.id),'Retirement staged in draft. Apply to confirm.'))]);
$('delete').onclick=()=>{const uses=d.uses(d.draft.id);modal('Delete '+d.draft.name+'?',el('p',uses.length?'Blocked: used by '+uses.map(x=>x.name).join(', ')+'. Remove references or retire the definition.':'No confirmed references found in this model. Published snapshots remain separate.'),[button('Delete definition',()=>closeAct(()=>d.deleteDefinition(d.draft.id),'Deletion staged in draft. Apply to confirm.'))]);};
$('publish').onclick=()=>modal('Publish simulation',el('p','This snapshots the confirmed catalog in RAM. It does not sign, upload or deploy anything.'),[button('Snapshot confirmed model',()=>closeAct(()=>d.publish(),'Simulated publication complete; no external changes.'))]);
$('simulate-remote').onclick=()=>act(()=>d.remoteChange(),'Confirmed generation advanced. Your draft base is now stale.');$('rebase').onclick=()=>act(()=>d.rebase(),'Prototype rebase acknowledged. Production requires a real change comparison.');render();globalThis.prototypeUI={d,render,renderPreview,widget,controls};})();
